function addressKind(text: string): string {
  const isDigit = (c: string) => c >= "0" && c <= "9";
  const isHex = (c: string) => isDigit(c) || (c >= "a" && c <= "f") || (c >= "A" && c <= "F");
  if (text.includes(".")) {
    const parts = text.split(".");
    if (parts.length !== 4) return "Neither";
    for (const p of parts) {
      if (p.length < 1 || p.length > 3) return "Neither";
      if (![...p].every(isDigit)) return "Neither";
      if (p.length > 1 && p[0] === "0") return "Neither";
      if (Number(p) > 255) return "Neither";
    }
    return "IPv4";
  }
  if (text.includes(":")) {
    const groups = text.split(":");
    if (groups.length !== 8) return "Neither";
    for (const g of groups) {
      if (g.length < 1 || g.length > 4 || ![...g].every(isHex)) return "Neither";
    }
    return "IPv6";
  }
  return "Neither";
}

